package com.rpb.reservation.workforce.leave.entitlement;
import static com.rpb.reservation.workforce.leave.entitlement.LeaveEntitlementDtos.*;
import com.rpb.reservation.workforce.application.WorkforceJson;import com.rpb.reservation.workforce.domain.WorkforceException;import java.sql.*;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository public class LeaveEntitlementRepository {
 private final JdbcTemplate jdbc;private final WorkforceJson json;
 public LeaveEntitlementRepository(JdbcTemplate jdbc,WorkforceJson json){this.jdbc=jdbc;this.json=json;}
 public UUID company(UUID tenant,UUID store){return jdbc.query("select operating_entity_id from stores where tenant_id=? and id=? and deleted_at is null",(r,n)->r.getObject(1,UUID.class),tenant,store).stream().findFirst().orElseThrow(WorkforceException::missing);}
 public List<Type> types(UUID tenant,UUID company){return jdbc.query("select t.id,t.name,t.store_id from workforce_leave_types t join stores s on s.tenant_id=t.tenant_id and s.id=t.store_id where t.tenant_id=? and s.operating_entity_id=? order by t.name,t.id",(r,n)->new Type(r.getObject(1,UUID.class),r.getString(2),r.getObject(3,UUID.class)),tenant,company);}
 public boolean typeInStore(UUID tenant,UUID store,UUID type){return Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from workforce_leave_types where tenant_id=? and store_id=? and id=?)",Boolean.class,tenant,store,type));}
 public boolean employed(UUID tenant,UUID employee,UUID company,int year){return Boolean.TRUE.equals(jdbc.queryForObject("with latest as (select distinct on(effective_date) company_id,effective_date from workforce_company_history where tenant_id=? and employee_id=? order by effective_date,version desc),periods as (select company_id,effective_date,lead(effective_date) over(order by effective_date) next_date from latest) select exists(select 1 from periods where company_id=? and effective_date<? and (next_date is null or next_date>?))",Boolean.class,tenant,employee,company,LocalDate.of(year+1,1,1),LocalDate.of(year,1,1)));}
 public Optional<Policy> latest(UUID tenant,UUID employee,UUID company,UUID type,int year){return jdbc.query("select * from workforce_leave_entitlements where tenant_id=? and employee_id=? and company_id=? and type_id=? and leave_year=? order by version desc limit 1",this::read,tenant,employee,company,type,year).stream().findFirst();}
 private Policy read(ResultSet r,int n)throws SQLException{return new Policy(r.getObject("id",UUID.class),r.getObject("company_id",UUID.class),r.getObject("employee_id",UUID.class),r.getObject("type_id",UUID.class),r.getInt("leave_year"),r.getBigDecimal("grant_units"),r.getBigDecimal("carry_units"),r.getBigDecimal("adjustment_units"),r.getString("unit"),r.getObject("day_minutes",Integer.class),r.getString("reason"),r.getLong("version"));}
 public void insert(UUID tenant,UUID store,UUID actor,Policy p){jdbc.update("insert into workforce_leave_entitlements(id,tenant_id,company_id,employee_id,type_id,source_store_id,leave_year,grant_units,carry_units,adjustment_units,unit,day_minutes,reason,version,actor_id) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",p.id(),tenant,p.companyId(),p.employeeId(),p.typeId(),store,p.year(),p.grant(),p.carryIn(),p.adjustment(),p.unit(),p.dayMinutes(),p.reason(),p.version(),actor);}
 public Optional<Policy> replay(UUID tenant,UUID command,UUID store,UUID employee,UUID actor,Write c){return jdbc.query("select * from workforce_leave_entitlement_commands where tenant_id=? and command_id=?",(r,n)->{if(!store.equals(r.getObject("store_id",UUID.class))||!employee.equals(r.getObject("employee_id",UUID.class))||!actor.equals(r.getObject("actor_id",UUID.class))||!c.equals(json.read(r.getString("request_json"),Write.class)))throw WorkforceException.conflict();return json.read(r.getString("response_json"),Policy.class);},tenant,command).stream().findFirst();}
 public void receipt(UUID tenant,UUID store,UUID employee,UUID actor,UUID command,Write c,Policy p){jdbc.update("insert into workforce_leave_entitlement_commands(tenant_id,command_id,store_id,employee_id,actor_id,request_json,response_json) values(?,?,?,?,?,?::jsonb,?::jsonb)",tenant,command,store,employee,actor,json.write(c),json.write(p));}
 public List<Event> events(UUID tenant,UUID company,UUID employee,int year){return jdbc.query("""
 select id,type_id,work_date,start_at,end_at,status from workforce_attendance_exceptions where tenant_id=? and company_id=? and employee_id=? and kind='leave' and work_date>=? and work_date<? and status in ('pending','approved','cancel_requested')
 union all
 select l.id,l.type_id,s.work_date,l.start_at,l.end_at,l.status from workforce_leaves l join workforce_schedules s on s.tenant_id=l.tenant_id and s.id=l.schedule_id where l.tenant_id=? and s.company_id=? and l.employee_id=? and s.work_date>=? and s.work_date<? and l.status in ('pending','approved','cancel_requested')
 """,(r,n)->new Event(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getObject(3,LocalDate.class),r.getTimestamp(4).toInstant(),r.getTimestamp(5).toInstant(),r.getString(6)),tenant,company,employee,LocalDate.of(year,1,1),LocalDate.of(year+1,1,1),tenant,company,employee,LocalDate.of(year,1,1),LocalDate.of(year+1,1,1));}
}
